state[8] = acadoVariables.x[index * 10 + 8];
state[9] = acadoVariables.x[index * 10 + 9];
state[180] = acadoVariables.u[index * 7];
state[181] = acadoVariables.u[index * 7 + 1];
state[182] = acadoVariables.u[index * 7 + 2];
