state[184] = acadoVariables.u[index * 7 + 4];
state[185] = acadoVariables.u[index * 7 + 5];
state[186] = acadoVariables.u[index * 7 + 6];
state[187] = acadoVariables.od[index * 4];
state[188] = acadoVariables.od[index * 4 + 1];
state[189] = acadoVariables.od[index * 4 + 2];
state[190] = acadoVariables.od[index * 4 + 3];

acado_integrate(state, index == 0);

acadoVariables.x[index * 10 + 10] = state[0];
acadoVariables.x[index * 10 + 11] = state[1];
acadoVariables.x[index * 10 + 12] = state[2];
acadoVariables.x[index * 10 + 13] = state[3];
